import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network issue: {e}")

    try:
        tree = html.fromstring(response.content)
        table_element = tree.xpath('//table')[0]
        rows = table_element.xpath('.//tr')
        if not rows:
            return 0

        headers = []
        data = []
        header_cells = rows[0].xpath('.//th')
        if header_cells:
            headers = [cell.text_content().strip() for cell in header_cells]
            rows = rows[1:]

        for row in rows:
            cells = row.xpath('.//td')
            if cells:
                row_data = [cell.text_content().strip() for cell in cells]
                data.append(row_data)

        if not data:
            return 0

        df = pd.DataFrame(data, columns=headers if headers else None)
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.close()
        return len(data)
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if webpage_url.startswith('http://') or webpage_url.startswith('https://'):
        try:
            response = requests.get(webpage_url, verify=False)
            response.raise_for_status()
            tree = html.fromstring(response.content)
        except requests.RequestException as e:
            raise requests.RequestException(f"Network issue: {e}")
    else:
        with open(webpage_url, 'r') as f:
            content = f.read()
        tree = html.fromstring(content)

    table_elements = tree.xpath('//table')
    if not table_elements:
        return 0

    table = table_elements[0]
    rows = table.xpath('.//tr')
    data = []
    for row in rows:
        cols = row.xpath('.//td|.//th')
        cols = [col.text_content().strip() for col in cols]
        data.append(cols)

    if not data:
        return 0

    df = pd.DataFrame(data[1:], columns=data[0] if data else None)

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

    return len(df)

